{"command":"python3 - <<'PY'
import json,subprocess
agents=['hot-topics','viral-titles','article-structure','rewrite-article','image-text','code_agent','after-sales','openclaw-optimizer']
results=[]
for a in agents:
    cmd=['openclaw','agent','--agent',a,'--message',f'[main-connectivity-test] ping from main at 2026-03-22 11:22 Asia/Shanghai, reply with PONG {a}','--json','--timeout','120']
    try:
        p=subprocess.run(cmd,capture_output=True,text=True,timeout=180)
        out=p.stdout.strip()
        err=p.stderr.strip()
        ok=(p.returncode==0)
        parsed=None
        if out:
            try:
                parsed=json.loads(out)
            except Exception:
                pass
        results.append({'agent':a,'ok':ok,'code':p.returncode,'stdout':out[:800],'stderr':err[:300],'parsed':parsed})
    except Exception as e:
        results.append({'agent':a,'ok':False,'error':str(e)})
print(json.dumps(results,ensure_ascii=False,indent=2))
PY"}

