{"command":"python3 - <<'PY'
import json,subprocess
agents=['hot-topics','viral-titles','article-structure','rewrite-article','image-text','code_agent','after-sales','openclaw-optimizer']
for a in agents:
    cmd=['openclaw','agent','--agent',a,'--message',f'[main-connectivity-test-2] 只回复 PONG {a}','--json','--timeout','90']
    p=subprocess.run(cmd,capture_output=True,text=True)
    status='FAIL'
    reply=''
    if p.returncode==0:
        try:
            j=json.loads(p.stdout)
            payloads=j.get('result',{}).get('payloads',[])
            if payloads:
                reply=payloads[0].get('text','').strip().replace('\n',' ')[:80]
            status='OK'
        except Exception as e:
            status='PARSE_ERR'
            reply=str(e)
    else:
        reply=(p.stderr or p.stdout).strip().replace('\n',' ')[:120]
    print(f"{a}\t{status}\t{returncode if (returncode:=p.returncode) is not None else ''}\t{reply}")
PY"}

